import * as React from "react"
import styled from "styled-components"
import Toc from "../../components/molecules/Toc"
import WikiContent from "../../components/molecules/WikiContent"
import device from "../../constants/device"
import theme from "../../constants/theme"
import Link from "../atoms/Link"
import Comments from "../molecules/Comments"
import HomeLink from "../molecules/HomeLink"
import RelatedLinks from "../molecules/RelatedLinks"
import GitHubCommitLink from "../organisms/GitHubCommitLink"
import PageLayout from "./layout/PageLayout"

const Main = styled.div`
  overflow: auto;

  ::before {
    content: "";
    background-color: ${theme.colors.background};
    inset: 0;
    position: fixed;
    z-index: -1;
  }
`

const TitleContainer = styled.div`
  display: flex;
  align-items: baseline;
  margin: 1rem 0;
  gap: 0.5rem;
`

const Title = styled.h1`
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  color: ${theme.colors.foreground};
`

const TitleBottom = styled.dl`
  display: grid;
  grid-template-columns: auto auto;
  column-gap: 0.25rem;
  justify-content: end;
  margin: 0;
  font-size: .7rem;
  color: ${theme.colors.lowlight};

  > dt {
    text-align: right;
  }

  > dd {
    margin: 0;
  }
`

const TocMain = styled(Toc)`
  display: block;

  @media (${device.larger}) {
    display: none;
  }
`

const TocSide = styled(Toc)`
  max-width: 20rem;
  margin-top: 1rem;
`

const RelatedLinksSide = styled(RelatedLinks)`
  max-width: 20rem;
`

export default function Wiki({
  title,
  tableOfContents,
  relatedLinks,
  wikiContents,
  created,
  lastModified,
  lastCommitHash,
  gitHubRepositoryUrl,
}: {
  title?: string;
  tableOfContents: string;
  relatedLinks: JSX.Element[];
  wikiContents: string;
  created?: Date;
  lastModified?: Date;
  lastCommitHash?: string;
  gitHubRepositoryUrl?: string;
  activityDates?: Date[];
}) {
  const githubLink = lastModified ? (
    <GitHubCommitLink
      lastModified={lastModified}
      gitHubRepositoryUrl={gitHubRepositoryUrl}
      hash={lastCommitHash}
    />
  ) : null

  return (
    <PageLayout
      header={
        <>
          <TitleContainer>
            <HomeLink />
            <Link href=".">
              <Title>{title}</Title>
            </Link>
          </TitleContainer>
          <TitleBottom>
            {created && (
              <>
                <dt>Created:</dt>
                <dd>{created.toLocaleDateString()}</dd>
              </>
            )}
            {githubLink && (
              <>
                <dt>Modified:</dt>
                <dd>{githubLink}</dd>
              </>
            )}
          </TitleBottom>
        </>
      }
    >
      <Main>
        <TocMain contents={tableOfContents} />
        <WikiContent contents={wikiContents} />
        <Comments />
      </Main>
      <RelatedLinksSide>{relatedLinks}</RelatedLinksSide>
      <TocSide contents={tableOfContents} />
    </PageLayout>
  )
}
